from pypdf import PdfReader
import re
r=PdfReader('/app/paper.pdf')
print('pages',len(r.pages))
terms=re.compile(r'(5,413|69,744|207 sessions|30 Hz|40 min|Bayesian decoding|decoding error|place cell|split-half|velocity|5 cm|five-fold|5-fold|neuron|mouse|mice)',re.I)
for i,p in enumerate(r.pages):
 t=p.extract_text() or ''
 lines=[x.strip() for x in t.splitlines()]
 hits=[]
 for j,x in enumerate(lines):
  if terms.search(x):
   hits.extend(lines[max(0,j-2):min(len(lines),j+3)])
 if hits:
  print('\n### PAGE',i+1)
  seen=[]
  for x in hits:
   if x and x not in seen: seen.append(x)
  print('\n'.join(seen[:120]))
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":40000});
